package net.hawyn.hnubl.discovery;
import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.iface.reference.*;
import com.android.tools.smali.dexlib2.immutable.*;import com.android.tools.smali.dexlib2.immutable.instruction.*;import com.android.tools.smali.dexlib2.immutable.reference.*;import com.android.tools.smali.dexlib2.rewriter.*;import com.android.tools.smali.dexlib2.writer.pool.DexPool;import com.google.gson.*;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
/** Genuine DEX references, constructor definitions and original reason bridges. */
public final class TerminalRebootDiscoveryTest {
 private static final String EXIT="Landroid/os/PowerManager;->reboot(Ljava/lang/String;)V";
 private static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 private static String key(MethodReference m){StringBuilder s=new StringBuilder(m.getDefiningClass()).append("->").append(m.getName()).append('(');for(CharSequence p:m.getParameterTypes())s.append(p);return s.append(')').append(m.getReturnType()).toString();}
 private static Set<String> refs(Method m){Set<String> out=new HashSet<>();if(m!=null&&m.getImplementation()!=null)for(Instruction i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction&&((ReferenceInstruction)i).getReference() instanceof MethodReference)out.add(key((MethodReference)((ReferenceInstruction)i).getReference()));return out;}
 public static void verify(File apk,JsonObject mapping)throws Exception{
  Map<String,ClassDef> types=new HashMap<>();Map<String,Method> methods=new HashMap<>();var dex=DexFileFactory.loadDexContainer(apk,null);for(String name:dex.getDexEntryNames())for(ClassDef c:dex.getEntry(name).getDexFile().getClasses()){types.put(c.getType(),c);for(Method m:c.getMethods())methods.put(key(m),m);}
  JsonObject terminal=null;for(JsonElement e:mapping.getAsJsonArray("hooks")){JsonObject h=e.getAsJsonObject();if(h.get("role").getAsString().equals("reboot_terminal"))terminal=h;}
  check(terminal!=null&&terminal.get("class_name").getAsString().equals("android.os.PowerManager")&&terminal.get("method_name").getAsString().equals("reboot"),"Actual framework terminal not discovered");
  for(JsonElement caller:terminal.getAsJsonArray("actual_callers"))check(refs(methods.get(caller.getAsString())).contains(EXIT),"Terminal caller metadata has no actual invoke");
  check(!mapping.getAsJsonArray("reboot_continuations").isEmpty(),"No original continuation");
  for(JsonElement e:mapping.getAsJsonArray("reboot_continuations")){JsonObject item=e.getAsJsonObject();String owner="L"+item.get("class_name").getAsString().replace('.','/')+";";ClassDef c=types.get(owner);check(c!=null&&c.getInterfaces().contains("Ljava/lang/Runnable;"),"Not an actual Runnable class");check(refs(methods.get(owner+"->run()V")).contains(EXIT),"Continuation does not call the actual terminal");for(JsonElement ctor:item.getAsJsonArray("constructors")){StringBuilder k=new StringBuilder(owner).append("-><init>(");for(JsonElement t:ctor.getAsJsonObject().getAsJsonArray("parameter_types"))k.append('L').append(t.getAsString().replace('.','/')).append(';');k.append(")V");check(methods.containsKey(k.toString()),"Constructor ABI does not match actual DEX");}}
  boolean bridge=false;for(JsonElement e:mapping.getAsJsonArray("hooks")){JsonObject h=e.getAsJsonObject();if(!h.get("role").getAsString().equals("reboot_context"))continue;bridge=true;String target="L"+h.get("class_name").getAsString().replace('.','/')+";->"+h.get("method_name").getAsString()+"(Ljava/lang/String;)V";check(refs(methods.get(h.get("forwarded_from").getAsString())).contains(target),"Reason bridge is not called by its proved source");check(!h.getAsJsonArray("manual_values").isEmpty()&&!h.getAsJsonArray("automatic_values").isEmpty(),"Discovered reason values lost at bridge");}
  check(bridge,"Actual associated-install reason bridge absent");
 }
 private static File mutate(File input,Path out,JsonObject mapping,String mode)throws Exception{
  Files.createDirectories(out);Set<String> owners=new HashSet<>();for(JsonElement e:mapping.getAsJsonArray("reboot_continuations"))owners.add("L"+e.getAsJsonObject().get("class_name").getAsString().replace('.','/')+";");
  DexRewriter r=new DexRewriter(new RewriterModule(){
   @Override public Rewriter<ClassDef> getClassDefRewriter(Rewriters all){return new ClassDefRewriter(all){@Override public ClassDef rewrite(ClassDef c){return new RewrittenClassDef(c){@Override public List<String> getInterfaces(){if(mode.equals("not-runnable")&&owners.contains(c.getType()))return List.of();return super.getInterfaces();}};}};}
   @Override public Rewriter<Instruction> getInstructionRewriter(Rewriters all){return ins->{if(mode.equals("no-terminal")&&ins instanceof ReferenceInstruction&&((ReferenceInstruction)ins).getReference() instanceof MethodReference){MethodReference m=(MethodReference)((ReferenceInstruction)ins).getReference();if(key(m).equals(EXIT)){var changed=new ImmutableMethodReference(m.getDefiningClass(),"fixture_not_a_reboot",m.getParameterTypes(),m.getReturnType());if(ins instanceof RegisterRangeInstruction){var x=(RegisterRangeInstruction)ins;return new ImmutableInstruction3rc(ins.getOpcode(),x.getStartRegister(),x.getRegisterCount(),changed);}var x=(FiveRegisterInstruction)ins;return new ImmutableInstruction35c(ins.getOpcode(),x.getRegisterCount(),x.getRegisterC(),x.getRegisterD(),x.getRegisterE(),x.getRegisterF(),x.getRegisterG(),changed);}}return ins;};}
  });var dex=DexFileFactory.loadDexContainer(input,null);Map<String,Path> files=new LinkedHashMap<>();for(String name:dex.getDexEntryNames()){Path p=out.resolve(name);DexPool.writeTo(p.toString(),r.getDexFileRewriter().rewrite(dex.getEntry(name).getDexFile()));files.put(name,p);}File result=out.resolve("TEST-ONLY-UNSIGNED.apk").toFile();try(ZipFile zip=new ZipFile(input);ZipOutputStream output=new ZipOutputStream(new FileOutputStream(result))){var entries=zip.entries();while(entries.hasMoreElements()){var e=entries.nextElement();if(e.isDirectory()||e.getName().startsWith("META-INF/"))continue;output.putNextEntry(new ZipEntry(e.getName()));if(files.containsKey(e.getName()))Files.copy(files.get(e.getName()),output);else try(InputStream stream=zip.getInputStream(e)){stream.transferTo(output);}output.closeEntry();}}return result;
 }
 public static void main(String[] args)throws Exception{check(args.length==2,"APK NEW_OUTPUT_DIRECTORY");File input=new File(args[0]);Path out=Path.of(args[1]);check(!Files.exists(out),"Exclusive output required");Files.createDirectories(out);JsonObject original=JsonParser.parseString(OucDiscovery.discover(input)).getAsJsonObject();verify(input,original);JsonObject report=new JsonObject();report.add("actual",original);for(String mode:List.of("no-terminal","not-runnable")){JsonObject bad=JsonParser.parseString(OucDiscovery.discover(mutate(input,out.resolve(mode),original,mode))).getAsJsonObject();check(!bad.get("discovery_complete").getAsBoolean(),"Missing critical terminal proof falsely ready");String expected=mode.equals("no-terminal")?"reboot_terminal":"reboot_continuation";check(bad.getAsJsonArray("critical_missing").asList().stream().anyMatch(v->v.getAsString().equals(expected)),"Wrong critical missing diagnosis");report.add(mode,bad.get("critical_missing"));}report.addProperty("passed",true);report.addProperty("deviceOperations",false);Files.writeString(out.resolve("report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report));System.out.println("Actual terminal and continuation DEX checks passed: "+out);}
}
